update_rule.pseudocode:
if t == 0:
  N <- params.n_agents
  if params.network_type == 'watts_strogatz':
    G <- watts_strogatz_graph(N, k=round(params.avg_degree), p=params.rewiring_prob, seed=random_seed)
  else if params.network_type == 'barabasi_albert':
    G <- barabasi_albert_graph(N, m=params.m_ba, seed=random_seed)
  assign age_group to each node using shares
  assign households by grouping nodes; connect additional intra-household edges with prob=params.household_cluster_prob
  for each edge (i,j) in G:
    w ~ Normal(params.edge_weight_mean, params.edge_weight_sd), clip to [0.1, 3]
    set tie_strength(i,j)=w
  adjust mixing by age homophily and risk assortativity via rewiring while preserving degree distribution
  output graph.social = G and initialized person attributes
